WITH "__duckstream_0" AS (SELECT t.c0 AS c0, CAST((t.c1 // CAST(3 AS INTEGER)) AS BIGINT) AS c1, CAST((t.c1 % CAST(3 AS INTEGER)) AS INTEGER) AS c2, CAST((CAST((t.c1 - CAST((CAST((CAST((t.c1 % CAST(86400 AS INTEGER)) AS INTEGER) + CAST(86400 AS INTEGER)) AS INTEGER) % CAST(86400 AS INTEGER)) AS INTEGER)) AS BIGINT) // CAST(86400 AS INTEGER)) AS BIGINT) AS c3, CAST(strpos(t.c2, t.c3) AS INTEGER) AS c4, substring(t.c2, CAST(4 AS INTEGER)) AS c5, substring(t.c2, CAST(1 AS INTEGER), CAST(3 AS INTEGER)) AS c6, CAST((CAST(((CASE WHEN t.c4 IS NULL OR isfinite(t.c4) THEN epoch_us(t.c4) ELSE error('finite TIMESTAMP required') END)::HUGEINT - (CASE WHEN make_timestamp(CAST(0 AS BIGINT)) IS NULL OR isfinite(make_timestamp(CAST(0 AS BIGINT))) THEN epoch_us(make_timestamp(CAST(0 AS BIGINT))) ELSE error('finite TIMESTAMP required') END)::HUGEINT) AS BIGINT) // 1000000) AS INTEGER) AS c7 FROM (SELECT "id" AS c0, "amount" AS c1, "haystack" AS c2, "needle" AS c3, "ts" AS c4 FROM "scalar_inputs") t)
SELECT CAST(result.c0 AS INTEGER) AS "id", CAST(result.c1 AS BIGINT) AS "quotient", CAST(result.c2 AS INTEGER) AS "remainder", CAST(result.c3 AS BIGINT) AS "day_index", CAST(result.c4 AS INTEGER) AS "position", CAST(result.c5 AS VARCHAR) AS "suffix", CAST(result.c6 AS VARCHAR) AS "prefix", CAST(result.c7 AS INTEGER) AS "seconds" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7 FROM "__duckstream_0" v) result;
